 import React, { useState, useEffect, useRef, useCallback } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import VerifiedBadge from '../components/VerifiedBadge'
import { initiatePayment } from '../services/paymentService'
import { uploadImage } from '../services/uploadService'
import { 
  Image, 
  Video, 
  X, 
  Loader,
  Play,
  Heart,
  Maximize2,
  Minimize2
} from 'lucide-react'

export default function CommunityDetail() {
    const { id } = useParams()
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [community, setCommunity] = useState(null)
    const [posts, setPosts] = useState([])
    const [isMember, setIsMember] = useState(false)
    const [isCreator, setIsCreator] = useState(false)
    const [loading, setLoading] = useState(true)
    const [showPaymentModal, setShowPaymentModal] = useState(false)
    const [newPost, setNewPost] = useState('')
    const [submitting, setSubmitting] = useState(false)
    const [showPredictionModal, setShowPredictionModal] = useState(false)
    const [predictionData, setPredictionData] = useState({
        result: 'Draw',
        yellowCards: 2,
        redCards: 0,
        corners: 5,
        offsides: 1
    })
    const [selectedMedia, setSelectedMedia] = useState(null)
    const [mediaPreview, setMediaPreview] = useState(null)
    const [mediaType, setMediaType] = useState(null)
    const [uploadingMedia, setUploadingMedia] = useState(false)
    const [fullscreenVideo, setFullscreenVideo] = useState(null)
    const fileInputRef = useRef(null)
    const videoRef = useRef(null)

    // Load community data
    const loadCommunityData = useCallback(async () => {
        setLoading(true)
        try {
            // Get community
            const { data: communityData } = await supabase
                .from('communities')
                .select('*, profiles:creator_id (id, username, full_name, avatar_url, is_verified)')
                .eq('id', id)
                .single()

            setCommunity(communityData)
            setIsCreator(user?.id === communityData?.creator_id)

            if (user) {
                const { data: memberData } = await supabase
                    .from('community_members')
                    .select('*')
                    .eq('community_id', id)
                    .eq('user_id', user.id)
                    .eq('status', 'active')
                    .maybeSingle()
                setIsMember(!!memberData)
            }

            // ✅ CRITICAL FIX: Get all posts with proper ordering
            const { data: postsData, error: postsError } = await supabase
                .from('community_posts')
                .select('*, profiles:user_id (id, username, full_name, avatar_url, is_verified)')
                .eq('community_id', id)
                .order('created_at', { ascending: false })

            if (postsError) {
                console.error('Posts error:', postsError)
            }

            console.log('📋 Posts loaded:', postsData?.length || 0)
            console.log('📋 Posts data:', postsData)
            setPosts(postsData || [])

            const { count } = await supabase
                .from('community_members')
                .select('*', { count: 'exact', head: true })
                .eq('community_id', id)
                .eq('status', 'active')

            if (communityData) {
                setCommunity({ ...communityData, member_count: count || 0 })
            }

        } catch (error) {
            console.error('Error loading community:', error)
            showToast('Failed to load community data', 'error')
        } finally {
            setLoading(false)
        }
    }, [id, user, showToast])

    useEffect(() => {
        loadCommunityData()
    }, [loadCommunityData])

    const toggleFullscreen = (videoUrl) => {
        setFullscreenVideo(fullscreenVideo === videoUrl ? null : videoUrl)
    }

    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape' && fullscreenVideo) {
                setFullscreenVideo(null)
            }
        }
        window.addEventListener('keydown', handleEsc)
        return () => window.removeEventListener('keydown', handleEsc)
    }, [fullscreenVideo])

    const handleJoin = () => {
        if (!user) {
            showToast('Please sign in to join this community', 'warning')
            navigate('/login')
            return
        }
        setShowPaymentModal(true)
    }

    const handlePayment = async () => {
        if (!user) {
            showToast('Please sign in first', 'error')
            return
        }

        setSubmitting(true)
        try {
            const { data: profileData } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .maybeSingle()

            if (!profileData) {
                await supabase
                    .from('profiles')
                    .insert({
                        id: user.id,
                        username: user.email?.split('@')[0] || 'user',
                        full_name: user.email?.split('@')[0] || 'user'
                    })
            }

            const { data: existingMember } = await supabase
                .from('community_members')
                .select('*')
                .eq('community_id', id)
                .eq('user_id', user.id)
                .maybeSingle()

            if (existingMember) {
                setShowPaymentModal(false)
                setIsMember(true)
                showToast('You are already a member!', 'info')
                setSubmitting(false)
                return
            }

            const amount = community.price || 50.00
            const paymentType = community.payment_type || 'monthly'
            const itemName = `${community.name} - ${paymentType === 'monthly' ? 'Monthly' : 'One-time'} Subscription`

            const result = await initiatePayment(
                id,
                user.id,
                amount,
                itemName
            )

            if (!result.success) {
                throw new Error(result.error)
            }

            const formElement = document.createElement('form')
            formElement.method = 'POST'
            formElement.action = result.payfastUrl
            
            Object.entries(result.payfastData).forEach(([key, value]) => {
                const input = document.createElement('input')
                input.type = 'hidden'
                input.name = key
                input.value = value
                formElement.appendChild(input)
            })
            
            document.body.appendChild(formElement)
            formElement.submit()
            
        } catch (error) {
            console.error('Payment error:', error)
            showToast('Failed to process payment: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleMediaSelect = (e, type) => {
        const file = e.target.files[0]
        if (!file) return

        const maxSize = type === 'video' ? 50 * 1024 * 1024 : 10 * 1024 * 1024
        if (file.size > maxSize) {
            showToast(`File too large. Max ${type === 'video' ? '50' : '10'}MB.`, 'error')
            return
        }

        if (type === 'image' && !file.type.startsWith('image/')) {
            showToast('Please select an image file.', 'error')
            return
        }
        if (type === 'video' && !file.type.startsWith('video/')) {
            showToast('Please select a video file.', 'error')
            return
        }

        if (type === 'video') {
            const video = document.createElement('video')
            video.preload = 'metadata'
            video.onloadedmetadata = () => {
                if (video.duration > 120) {
                    showToast('Video must be 2 minutes or less.', 'error')
                    e.target.value = ''
                    return
                }
                proceedWithMedia(file, type)
            }
            video.src = URL.createObjectURL(file)
            video.onerror = () => {
                proceedWithMedia(file, type)
            }
            return
        }

        proceedWithMedia(file, type)
    }

    const proceedWithMedia = (file, type) => {
        setSelectedMedia(file)
        setMediaType(type)
        
        const reader = new FileReader()
        reader.onload = () => {
            setMediaPreview(reader.result)
        }
        reader.readAsDataURL(file)
        
        if (fileInputRef.current) {
            fileInputRef.current.value = ''
        }
    }

    const removeMedia = () => {
        setSelectedMedia(null)
        setMediaPreview(null)
        setMediaType(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ''
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        if (!newPost.trim() && !selectedMedia) {
            showToast('Please write something or add media', 'warning')
            return
        }
        if (!isCreator) {
            showToast('Only the community creator can post in this community', 'error')
            return
        }

        setUploadingMedia(true)
        setSubmitting(true)

        try {
            let mediaUrl = null
            let mediaTypeSaved = null

            if (selectedMedia) {
                const bucket = mediaType === 'video' ? 'community-videos' : 'community-images'
                try {
                    console.log('📤 Uploading media to bucket:', bucket)
                    console.log('📄 File name:', selectedMedia.name)
                    console.log('📏 File size:', selectedMedia.size)
                    
                    mediaUrl = await uploadImage(selectedMedia, user.id, bucket)
                    mediaTypeSaved = mediaType
                    
                    console.log('✅ Upload successful, URL:', mediaUrl)
                } catch (error) {
                    console.error('❌ Upload error:', error)
                    showToast('Failed to upload media: ' + error.message, 'error')
                    setUploadingMedia(false)
                    setSubmitting(false)
                    return
                }
            }

            const postData = {
                community_id: id,
                user_id: user.id,
                text: newPost.trim() || null
            }

            if (predictionData.result) {
                postData.prediction_data = predictionData
            }

            if (mediaUrl) {
                postData.media_url = mediaUrl
                postData.media_type = mediaTypeSaved
            }

            console.log('📝 Creating post with data:', postData)

            const { data, error } = await supabase
                .from('community_posts')
                .insert(postData)
                .select()
                .single()

            if (error) {
                console.error('❌ Post creation error:', error)
                throw error
            }

            console.log('✅ Post created successfully:', data)

            // Update community post count
            const { data: communityData } = await supabase
                .from('communities')
                .select('post_count')
                .eq('id', id)
                .single()

            await supabase
                .from('communities')
                .update({ post_count: (communityData?.post_count || 0) + 1 })
                .eq('id', id)

            // Reset form
            setNewPost('')
            setPredictionData({
                result: 'Draw',
                yellowCards: 2,
                redCards: 0,
                corners: 5,
                offsides: 1
            })
            removeMedia()
            
            // ✅ CRITICAL: Reload posts after creating
            await loadCommunityData()
            
            showToast('Post created successfully!', 'success')
        } catch (error) {
            console.error('❌ Error creating post:', error)
            showToast('Failed to create post: ' + error.message, 'error')
        } finally {
            setUploadingMedia(false)
            setSubmitting(false)
        }
    }

    const handleLike = async (postId) => {
        if (!user) {
            showToast('Please sign in to like posts', 'warning')
            return
        }

        try {
            const { data: existing } = await supabase
                .from('community_post_likes')
                .select('*')
                .eq('post_id', postId)
                .eq('user_id', user.id)
                .maybeSingle()

            const { data: postData } = await supabase
                .from('community_posts')
                .select('likes_count')
                .eq('id', postId)
                .single()

            const currentLikes = postData?.likes_count || 0

            if (existing) {
                await supabase
                    .from('community_post_likes')
                    .delete()
                    .eq('post_id', postId)
                    .eq('user_id', user.id)

                await supabase
                    .from('community_posts')
                    .update({ likes_count: Math.max(0, currentLikes - 1) })
                    .eq('id', postId)
            } else {
                await supabase
                    .from('community_post_likes')
                    .insert({ post_id: postId, user_id: user.id })

                await supabase
                    .from('community_posts')
                    .update({ likes_count: currentLikes + 1 })
                    .eq('id', postId)
            }

            loadCommunityData()
        } catch (error) {
            console.error('Error liking post:', error)
            showToast('Failed to like post. Please try again.', 'error')
        }
    }

    const renderVideo = (videoUrl) => {
        return (
            <div className="relative group">
                <video 
                    src={videoUrl}
                    className="w-full max-h-[500px] object-contain bg-black rounded-lg"
                    controls
                    playsInline
                    controlsList="nodownload"
                    preload="metadata"
                    ref={videoRef}
                />
                <button
                    onClick={() => toggleFullscreen(videoUrl)}
                    className="absolute bottom-4 right-4 bg-black/70 hover:bg-black text-white p-2 rounded-lg transition opacity-0 group-hover:opacity-100"
                    title="Fullscreen"
                >
                    <Maximize2 size={20} />
                </button>
            </div>
        )
    }

    const canPost = isCreator

    if (loading) {
        return <div className="text-center py-12"><div className="text-gray-500">Loading...</div></div>
    }

    if (!community) {
        return (
            <div className="text-center py-12 bg-white rounded-xl shadow-md">
                <div className="text-4xl mb-4">🔍</div>
                <p className="text-gray-500">Community not found</p>
                <Link to="/community" className="text-green-600 hover:underline mt-4 block">← Back to Communities</Link>
            </div>
        )
    }

    return (
        <div>
            {/* Fullscreen Video Modal */}
            {fullscreenVideo && (
                <div 
                    className="fixed inset-0 bg-black z-[9999] flex items-center justify-center p-4"
                    onClick={() => setFullscreenVideo(null)}
                >
                    <div className="relative w-full max-w-7xl max-h-screen" onClick={(e) => e.stopPropagation()}>
                        <video 
                            src={fullscreenVideo}
                            className="w-full h-full max-h-screen object-contain"
                            controls
                            autoPlay
                            playsInline
                            controlsList="nodownload"
                            preload="metadata"
                        />
                        <button
                            onClick={() => setFullscreenVideo(null)}
                            className="absolute top-4 right-4 bg-black/70 hover:bg-black text-white p-3 rounded-full transition z-50"
                        >
                            <X size={24} />
                        </button>
                        <button
                            onClick={() => setFullscreenVideo(null)}
                            className="absolute bottom-4 right-4 bg-black/70 hover:bg-black text-white p-2 rounded-lg transition"
                        >
                            <Minimize2 size={20} />
                        </button>
                        <p className="absolute bottom-4 left-4 text-white/60 text-sm bg-black/50 px-3 py-1 rounded">
                            Press ESC to exit fullscreen
                        </p>
                    </div>
                </div>
            )}

            {/* Community Header */}
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-start justify-between">
                    <div>
                        <div className="flex items-center gap-2">
                            <span className="text-3xl">🏛️</span>
                            <h1 className="text-2xl font-bold text-gray-800">{community.name}</h1>
                            {isCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>}
                            {isMember && !isCreator && <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">✓ Member</span>}
                        </div>
                        <p className="text-gray-500 mt-1">{community.description || 'A private community for football predictions'}</p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R{community.price || 50} {community.payment_type === 'monthly' ? '/month' : 'once'}</span>
                        </div>
                        {isCreator && (
                            <div className="mt-2 text-sm text-green-600">
                                💰 You earn 70% per {community.payment_type === 'monthly' ? 'month' : 'payment'}
                            </div>
                        )}
                    </div>
                    <div>
                        {isCreator ? (
                            <span className="text-sm bg-yellow-100 text-yellow-800 px-4 py-2 rounded-lg">Creator</span>
                        ) : isMember ? (
                            <span className="text-sm bg-green-100 text-green-800 px-4 py-2 rounded-lg">✓ Member</span>
                        ) : (
                            <button onClick={handleJoin} className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium">
                                Join {community.payment_type === 'monthly' ? 'R' + (community.price || 50) + '/month' : 'R' + (community.price || 50) + ' once'}
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {canPost ? (
                <>
                    {/* Create Post Form */}
                    <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                        <form onSubmit={handleCreatePost} className="space-y-3">
                            <div className="flex gap-3">
                                <input 
                                    type="text" 
                                    value={newPost} 
                                    onChange={(e) => setNewPost(e.target.value)} 
                                    placeholder="📢 Share your community announcement..." 
                                    className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" 
                                />
                                <button 
                                    type="button" 
                                    onClick={() => setShowPredictionModal(true)} 
                                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition whitespace-nowrap"
                                >
                                    📊 Add Prediction
                                </button>
                                <button 
                                    type="submit" 
                                    disabled={submitting || (!newPost.trim() && !selectedMedia)} 
                                    className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 whitespace-nowrap"
                                >
                                    {submitting ? 'Posting...' : 'Post'}
                                </button>
                            </div>

                            {/* Media Upload Buttons */}
                            <div className="flex flex-wrap gap-2 items-center">
                                <label className="cursor-pointer">
                                    <input
                                        ref={fileInputRef}
                                        type="file"
                                        accept="image/*"
                                        onChange={(e) => handleMediaSelect(e, 'image')}
                                        className="hidden"
                                        disabled={uploadingMedia}
                                    />
                                    <div className="flex items-center gap-1 px-3 py-1.5 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm text-gray-700 transition">
                                        <Image size={16} /> Image
                                    </div>
                                </label>
                                <label className="cursor-pointer">
                                    <input
                                        type="file"
                                        accept="video/*"
                                        onChange={(e) => handleMediaSelect(e, 'video')}
                                        className="hidden"
                                        disabled={uploadingMedia}
                                    />
                                    <div className="flex items-center gap-1 px-3 py-1.5 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm text-gray-700 transition">
                                        <Video size={16} /> Video (2 min max)
                                    </div>
                                </label>
                                {uploadingMedia && (
                                    <div className="flex items-center gap-1 px-3 py-1.5 text-sm text-gray-500">
                                        <Loader size={16} className="animate-spin" /> Uploading...
                                    </div>
                                )}
                            </div>

                            {/* Media Preview */}
                            {mediaPreview && (
                                <div className="relative">
                                    {mediaType === 'image' ? (
                                        <img 
                                            src={mediaPreview} 
                                            alt="Preview" 
                                            className="max-h-64 rounded-lg object-contain bg-gray-50 w-full"
                                        />
                                    ) : (
                                        <div className="relative">
                                            <video 
                                                src={mediaPreview} 
                                                className="max-h-64 rounded-lg object-contain bg-black w-full"
                                                controls
                                                playsInline
                                            />
                                            <div className="absolute inset-0 flex items-center justify-center bg-black/10 rounded-lg pointer-events-none">
                                                <Play size={48} className="text-white/70" />
                                            </div>
                                        </div>
                                    )}
                                    <button
                                        type="button"
                                        onClick={removeMedia}
                                        className="absolute top-2 right-2 bg-gray-800 text-white rounded-full w-8 h-8 flex items-center justify-center hover:bg-gray-700 transition"
                                    >
                                        <X size={18} />
                                    </button>
                                    <div className="absolute bottom-2 right-2 bg-black/70 text-white text-xs px-2 py-1 rounded">
                                        {mediaType === 'image' ? 'Image' : 'Video (2 min max)'}
                                    </div>
                                </div>
                            )}

                            <p className="text-xs text-gray-400 mt-2">👑 As the creator, your posts are highlighted</p>
                        </form>
                    </div>

                    {/* Posts List */}
                    {posts.length === 0 ? (
                        <div className="text-center py-12 bg-white rounded-xl shadow-md">
                            <div className="text-4xl mb-4">📝</div>
                            <p className="text-gray-500">No posts yet</p>
                            <p className="text-sm text-gray-400">{isCreator ? 'Be the first to share an announcement!' : 'The creator hasn\'t posted anything yet.'}</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {posts.map((post) => {
                                const isPostCreator = post.user_id === community.creator_id
                                return (
                                    <div key={post.id} className={`bg-white rounded-xl shadow-md p-4 ${isPostCreator ? 'border-2 border-yellow-400' : ''}`}>
                                        <div className="flex items-center gap-3 mb-3">
                                            <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold overflow-hidden">
                                                {post.profiles?.avatar_url ? (
                                                    <img src={post.profiles.avatar_url} alt={post.profiles.username} className="w-full h-full object-cover" />
                                                ) : (
                                                    post.profiles?.username?.[0]?.toUpperCase() || 'U'
                                                )}
                                            </div>
                                            <div>
                                                <div className="font-semibold flex items-center gap-1.5">
                                                    {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                                    {post.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                                    {isPostCreator && <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full">👑 Admin</span>}
                                                </div>
                                                <div className="text-xs text-gray-400">@{post.profiles?.username} • {new Date(post.created_at).toLocaleDateString()}</div>
                                            </div>
                                        </div>
                                        
                                        <p className="text-gray-800 mb-3">{post.text}</p>
                                        
                                        {/* Media Display */}
                                        {post.media_url && (
                                            <div className="mb-3 rounded-lg overflow-hidden bg-black/5">
                                                {post.media_type === 'image' ? (
                                                    <img 
                                                        src={post.media_url} 
                                                        alt="Post media" 
                                                        className="w-full max-h-[500px] object-contain bg-black/5"
                                                        loading="lazy"
                                                    />
                                                ) : post.media_type === 'video' ? (
                                                    renderVideo(post.media_url)
                                                ) : null}
                                            </div>
                                        )}
                                        
                                        {post.prediction_data && (
                                            <div className="bg-gray-50 rounded-lg p-3 mb-3">
                                                <div className="flex items-center justify-between text-sm">
                                                    <span>📊 {post.prediction_data.result || 'Draw'}</span>
                                                    <span>🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                                    <span>🏁{post.prediction_data.corners || 0}</span>
                                                </div>
                                            </div>
                                        )}
                                        
                                        <button onClick={() => handleLike(post.id)} className="flex items-center gap-1 text-sm text-gray-400 hover:text-red-500 transition">
                                            <Heart size={16} className={post.likes_count > 0 ? 'fill-red-500 text-red-500' : ''} />
                                            {post.likes_count || 0}
                                        </button>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </>
            ) : (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">🔒</div>
                    <p className="text-gray-500">This community is private</p>
                    <p className="text-sm text-gray-400">Only the creator can post in this community</p>
                    {!isMember && !isCreator && (
                        <button onClick={handleJoin} className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition">Join Now</button>
                    )}
                    {isMember && !isCreator && <p className="mt-4 text-sm text-green-600">✅ You are a member of this community</p>}
                </div>
            )}

            {/* Payment Modal */}
            {showPaymentModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4">💳 Join {community.name}</h2>
                        
                        <div className="bg-gray-50 rounded-lg p-4 mb-4">
                            <div className="flex justify-between items-center">
                                <span className="text-gray-600">
                                    {community.payment_type === 'monthly' ? 'Monthly subscription' : 'One-time payment'}
                                </span>
                                <span className="font-bold text-xl">R{community.price || 50}</span>
                            </div>
                            <div className="flex justify-between items-center text-sm text-gray-500 border-t pt-2 mt-2">
                                <span>💰 You support this creator</span>
                                <span className="text-green-600 font-medium">70% goes to creator</span>
                            </div>
                            <p className="text-xs text-gray-400 mt-2">
                                {community.payment_type === 'monthly' 
                                    ? 'Cancel anytime. You\'ll be charged R' + (community.price || 50) + '/month.' 
                                    : 'One-time payment. No recurring charges.'}
                            </p>
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowPaymentModal(false)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handlePayment}
                                disabled={submitting}
                                className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {submitting ? (
                                    <>
                                        <span className="animate-spin">⏳</span> Processing...
                                    </>
                                ) : (
                                    <>
                                        💳 Pay R{community.price || 50}
                                    </>
                                )}
                            </button>
                        </div>

                        <p className="text-xs text-gray-400 text-center mt-4">
                            You will be redirected to PayFast to complete payment securely.
                        </p>
                    </div>
                </div>
            )}

            {/* Prediction Modal */}
            {showPredictionModal && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6 max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">📊 Add Prediction</h3>
                            <button onClick={() => setShowPredictionModal(false)} className="text-gray-400 hover:text-gray-600 text-2xl">×</button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">🏆 Result</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['Home Win', 'Draw', 'Away Win'].map((result) => (
                                        <button 
                                            key={result} 
                                            onClick={() => setPredictionData({...predictionData, result})} 
                                            className={`px-3 py-2 rounded-lg text-sm font-medium transition ${predictionData.result === result ? 'bg-green-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
                                        >
                                            {result === 'Home Win' ? '🏠 Home' : result === 'Away Win' ? '✈️ Away' : '🤝 Draw'}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🟨 Yellow Cards</label>
                                    <input 
                                        type="number" 
                                        min="0" 
                                        max="10" 
                                        value={predictionData.yellowCards} 
                                        onChange={(e) => setPredictionData({...predictionData, yellowCards: parseInt(e.target.value) || 0})} 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🟥 Red Cards</label>
                                    <input 
                                        type="number" 
                                        min="0" 
                                        max="5" 
                                        value={predictionData.redCards} 
                                        onChange={(e) => setPredictionData({...predictionData, redCards: parseInt(e.target.value) || 0})} 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🏁 Corners</label>
                                    <input 
                                        type="number" 
                                        min="0" 
                                        max="20" 
                                        value={predictionData.corners} 
                                        onChange={(e) => setPredictionData({...predictionData, corners: parseInt(e.target.value) || 0})} 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">🚩 Offsides</label>
                                    <input 
                                        type="number" 
                                        min="0" 
                                        max="10" 
                                        value={predictionData.offsides} 
                                        onChange={(e) => setPredictionData({...predictionData, offsides: parseInt(e.target.value) || 0})} 
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500" 
                                    />
                                </div>
                            </div>
                            <button 
                                onClick={() => { 
                                    setShowPredictionModal(false); 
                                    showToast('Prediction added to your post! Submit the post to save it.', 'success') 
                                }} 
                                className="w-full bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition"
                            >
                                Add to Post
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
